    time_bands jsonb DEFAULT '[{"id": "morning", "end": "12:00", "name": "Morning", "start": "06:00"}, {"id": "afternoon", "end": "17:00", "name": "Afternoon", "start": "12:00"}, {"id": "evening", "end": "22:00", "name": "Evening", "start": "17:00"}]'::jsonb NOT NULL,
    start_by_warning_minutes integer DEFAULT 30 NOT NULL,
    default_transport_mode text,
    session_break_minutes integer DEFAULT 15 NOT NULL,
    leave_by_lead_minutes integer DEFAULT 10 NOT NULL,
    bedtime_deviation_minutes integer DEFAULT 180 NOT NULL,
    pulse_publish_enabled boolean DEFAULT false NOT NULL,
    recovery_start_time time without time zone,
    recovery_end_time time without time zone,
    recovery_weekdays jsonb,
    estimate_calibration_enabled boolean DEFAULT true NOT NULL,
    pulse_unknown_to_off_minutes integer,
    pulse_further_prompts integer,
    pulse_unknown_hard_off_minutes integer,
    plan_code_pattern text,
    CONSTRAINT user_preferences_arrival_margin_check CHECK (((arrival_margin_minutes >= 0) AND (arrival_margin_minutes <= 60))),
    CONSTRAINT user_preferences_bedtime_deviation_check CHECK (((bedtime_deviation_minutes >= 0) AND (bedtime_deviation_minutes <= 720))),
    CONSTRAINT user_preferences_default_transport_mode_check CHECK (((default_transport_mode IS NULL) OR (default_transport_mode = ANY (ARRAY['car'::text, 'bike'::text, 'walk'::text])))),
    CONSTRAINT user_preferences_disruption_retro_fallback_check CHECK (((disruption_retro_fallback_minutes >= 1) AND (disruption_retro_fallback_minutes <= 1440))),
    CONSTRAINT user_preferences_leave_by_lead_check CHECK (((leave_by_lead_minutes >= 0) AND (leave_by_lead_minutes <= 60))),
    CONSTRAINT user_preferences_max_awake_check CHECK (((max_awake_hours >= 8) AND (max_awake_hours <= 36))),
    CONSTRAINT user_preferences_recovery_window_check CHECK ((((recovery_start_time IS NULL) AND (recovery_end_time IS NULL)) OR ((recovery_start_time IS NOT NULL) AND (recovery_end_time IS NOT NULL) AND (recovery_start_time <> recovery_end_time)))),
    CONSTRAINT user_preferences_session_break_check CHECK (((session_break_minutes >= 0) AND (session_break_minutes <= 120))),
    CONSTRAINT user_preferences_setup_buffer_check CHECK (((default_setup_buffer_minutes >= 0) AND (default_setup_buffer_minutes <= 1440))),
    CONSTRAINT user_preferences_sleep_duration_check CHECK (((minimum_sleep_minutes >= 60) AND (minimum_sleep_minutes <= desired_sleep_minutes) AND (desired_sleep_minutes <= 960))),
    CONSTRAINT user_preferences_start_by_warning_check CHECK (((start_by_warning_minutes >= 0) AND (start_by_warning_minutes <= 240))),
    CONSTRAINT user_preferences_submission_buffer_check CHECK (((submission_buffer_minutes >= 0) AND (submission_buffer_minutes <= 1440))),
    CONSTRAINT user_preferences_submission_percent_check CHECK (((submission_buffer_percent >= (0)::numeric) AND (submission_buffer_percent <= (1)::numeric))),
    CONSTRAINT user_preferences_transition_buffer_check CHECK (((default_transition_buffer_minutes >= 0) AND (default_transition_buffer_minutes <= 1440))),
    CONSTRAINT user_preferences_usable_fraction_check CHECK (((default_usable_fraction > (0)::numeric) AND (default_usable_fraction <= (1)::numeric)))
);
--> statement-breakpoint
